{"version":3,"file":"health_log_filter.min.js","sources":["../src/health_log_filter.js"],"sourcesContent":["/**\n * Health logs filter for Service Schema view page.\n *\n * @module     local_servicemanager/health_log_filter\n * @copyright  2026 Didactika.org\n * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later\n */\n\n/**\n * Initialize the filter.\n */\nexport const init = () => {\n    const filter = document.getElementById('healthlog-status-filter');\n    const table = document.getElementById('healthlog-table');\n\n    if (!filter || !table) {\n        return;\n    }\n\n    filter.addEventListener('change', (e) => {\n        const selectedStatus = e.target.value;\n        const rows = table.querySelectorAll('tbody tr');\n\n        rows.forEach(row => {\n            const status = row.getAttribute('data-status');\n            if (!selectedStatus || status === selectedStatus) {\n                row.style.display = '';\n            } else {\n                row.style.display = 'none';\n            }\n        });\n    });\n};\n"],"names":["filter","document","getElementById","table","addEventListener","e","selectedStatus","target","value","querySelectorAll","forEach","row","status","getAttribute","style","display"],"mappings":"sKAWoB,WACVA,OAASC,SAASC,eAAe,2BACjCC,MAAQF,SAASC,eAAe,mBAEjCF,QAAWG,OAIhBH,OAAOI,iBAAiB,UAAWC,UACzBC,eAAiBD,EAAEE,OAAOC,MACnBL,MAAMM,iBAAiB,YAE/BC,SAAQC,YACHC,OAASD,IAAIE,aAAa,eAI5BF,IAAIG,MAAMC,QAHTT,gBAAkBM,SAAWN,eAGV,OAFA"}
